function syncAccountUI(){const initials=accountState.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();document.querySelectorAll('.own-verified-mark').forEach(x=>x.hidden=!hasBlueCheck());const account=document.querySelector('.account');if(account){account.querySelector('.avatar').textContent=initials;account.querySelector('b').textContent=accountState.name;account.querySelector('small').textContent=accountState.handle;account.setAttribute('role','button');account.tabIndex=0;account.title='Buka akun dan verifikasi'}const own=document.querySelector('#profile .profile');if(own){own.querySelector('.avatar').textContent=initials;own.querySelector('h2').innerHTML=`${accountState.name} <small class="own-verified-mark blue-check" ${hasBlueCheck()?'':'hidden'}>✓</small>`;own.querySelector('.muted').textContent=accountState.handle}}
