function adminPage(title,subtitle,body){return `<div class="admin-shell"><nav class="admin-nav"><div><b>temm<span>oo</span></b><small>ADMIN CONSOLE</small></div>${[['Ringkasan',57],['Verified',58],['Moderasi',59],['Pengguna',60],['Event & Promotor',61],['Audit log',62]].map(x=>`<button class="${flowCurrent===x[1]?'active':''}" data-go="${x[1]}">${x[0]}</button>`).join('')}<button class="admin-exit" data-admin-logout>Keluar admin</button></nav><main class="admin-main"><header><div><small>TEMMOO ADMIN · ${accountState.role.replace('_',' ').toUpperCase()}</small><h1>${title}</h1><p>${subtitle}</p></div><span class="admin-user">TO</span></header>${body}</main></div>`}
function promoterPage(title,subtitle,body){return `<div class="promoter-shell"><nav class="promoter-nav"><div><b>temm<span>oo</span></b><small>PROMOTOR STUDIO</small></div><button class="${flowCurrent===64?'active':''}" data-go="64">Ringkasan</button><button class="${flowCurrent===65?'active':''}" data-go="65">Kelola event</button><button data-promoter-preview>Pratinjau publik</button><button data-go="56">Kembali ke akun</button></nav><main class="promoter-main"><header><div><small>${promoterState.organization.toUpperCase()} · TERVERIFIKASI</small><h1>${title}</h1><p>${subtitle}</p></div><span class="promoter-user">${promoterState.organization.split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase()}</span></header>${body}</main></div>`}
