function eventGroupData(kind=0){
  if(kind>=2){const custom=groupFlowState.customGroups[kind-2];return custom?{...custom,...groupInfoState[kind],kind}:{kind,name:'Grup baru',avatar:'GB',tone:'teal',members:1,message:'Belum ada pesan',description:''}}
  const event=selectedEvent(),short=event[0].replace(' 2026','');
  const base=kind===0
    ? {kind,name:`Circle ${short.replace('+62 Coffee R-I Fest','Coffee Fest')}`,avatar:'CF',tone:'gold',members:86,message:'Kevin: ketemu di gate utama ya',description:`Grup resmi untuk informasi, koordinasi, dan teman baru di ${short}.`}
    : {kind,name:'Berangkat dari Surabaya',avatar:'SB',tone:'teal',members:24,message:`Ada yang berangkat bareng ke ${short}?`,description:`Koordinasi keberangkatan bareng dari Surabaya menuju ${short}.`};
  return {...base,...groupInfoState[kind]};
}
function allEventGroups(){return [eventGroupData(0),eventGroupData(1),...groupFlowState.customGroups.map((_,i)=>eventGroupData(i+2))].filter(g=>!g.deleted)}
function defaultGroupMembers(){return [{name:'iwang',avatar:'I',tone:'',role:'admin',self:true},{name:'Nadia Aulia',avatar:'NA',tone:'teal',role:'admin'},{name:'Kevin Ardana',avatar:'KA',tone:'gold',role:'member'},{name:'Salsa Putri',avatar:'SP',tone:'',role:'member'}]}
const eventEndDates=['2026-10-11','2026-11-22','2026-12-07','2026-12-14','2026-12-21','2027-01-10','2027-01-18','2027-01-25','2026-08-25'];
function groupLifecycle(group){const end=new Date((group.eventEndDate||eventEndDates[activeEvent]||eventEndDates[0])+'T00:00:00'),archiveAt=new Date(end);archiveAt.setDate(archiveAt.getDate()+Number(group.archiveAfterDays||30));const now=new Date();if(group.lifecycle==='archived'||now>=archiveAt)return {key:'archived',label:'Diarsipkan',hint:'Hanya dapat dibaca'};if(now>=end||currentAttendance().status==='attended')return {key:'postevent',label:'Pasca-event',hint:'Bagikan pengalaman dan momen'};return {key:'active',label:'Aktif',hint:'Koordinasi sebelum dan selama event'}}
function lifecycleBadge(group){const life=groupLifecycle(group);return `<span class="group-life ${life.key}">${life.label}</span>`}
