function saveGroupInfo(group){groupInfoState[group.kind]={name:group.name,avatar:group.avatar,photo:group.photo||'',description:group.description,memberLimit:group.memberLimit,approval:group.approval||'admin',sendPermission:group.sendPermission||'all',archiveAfterDays:Number(group.archiveAfterDays||30),eventEndDate:group.eventEndDate||eventEndDates[activeEvent],lifecycle:group.lifecycle||'',closed:!!group.closed,deleted:!!group.deleted,members:group.members,membersList:group.membersList||defaultGroupMembers(),systemEvents:group.systemEvents||[]};localStorage.setItem(groupInfoKey,JSON.stringify(groupInfoState))}
function currentAttendance(){return attendanceState[activeEvent]||{status:'none',reason:''}}
function saveAttendance(status,reason=''){
  attendanceState[activeEvent]={status,reason};
  localStorage.setItem(attendanceKey,JSON.stringify(attendanceState));
}
function statusStrip(){const value=currentAttendance(),meta=attendanceMeta[value.status];return `<div class="event-status-strip ${value.status}"><span>${meta[1]}</span><div><small>STATUS KEHADIRANMU</small><b>${meta[0]}</b>${value.reason?`<em>${value.reason}</em>`:''}</div><button data-change-attendance>Ubah</button></div>`}
function attendancePicker(){const active=currentAttendance().status;return `${eventHero()}${eventTabs(22)}<div class="flow-body">${statusStrip()}<div class="info-card"><h3>Pilih rencana kehadiran</h3><p>Status ini mengatur rekomendasi Circle, pengingat, dan akses Ruang Event.</p></div><div class="status-options attendance-options"><button class="status-option ${active==='interested'?'selected':''}" data-set-attendance="interested"><b>♡ Tertarik</b><span>Simpan event tanpa menyatakan akan datang</span></button><button class="status-option ${active==='considering'?'selected':''}" data-set-attendance="considering"><b>🤔 Masih mikir</b><span>Catat alasan agar rekomendasi lebih relevan</span></button><button class="status-option ${active==='going'?'selected':''}" data-set-attendance="going"><b>🔥 Mau datang</b><span>Aktifkan persiapan, Circle, grup, dan check-in</span></button>${active==='attended'?'<div class="status-option selected locked"><b>✓ Sudah hadir</b><span>Status tercatat melalui check-in</span></div>':''}</div></div>`}
function eventHub(){const value=currentAttendance(),meta=attendanceMeta[value.status],going=['going','attended'].includes(value.status),attended=value.status==='attended';return `${eventHero()}<div class="event-hub">${statusStrip()}<div class="hub-countdown"><span>${attended?'EVENT TELAH KAMU HADIRI':'EVENT DIMULAI DALAM'}</span><b>${attended?'Momen tersimpan':'12 hari'}</b><small>${selectedEvent()[1]} 2026 · 10.00</small></div>${!going?`<div class="hub-gate"><h3>${value.status==='considering'?'Masih mempertimbangkan event ini':value.status==='interested'?'Event sudah disimpan':'Tentukan rencana kehadiranmu'}</h3><p>${value.reason?`Alasanmu: ${value.reason}. `:''}Pilih Mau Datang untuk membuka rekomendasi Circle, grup event, dan persiapan check-in.</p><button class="wide" data-set-attendance="going">Saya mau datang</button><button class="wide secondary" data-change-attendance>Ubah status</button></div>`:`<div class="hub-progress"><h3>Persiapanmu</h3><div><span class="done">✓</span><p><b>Status kehadiran</b><small>${meta[0]}</small></p><button data-change-attendance>Ubah</button></div><div><span>${attended?'✓':'2'}</span><p><b>Tiket event</b><small>${attended?'Sudah digunakan':'Belum dihubungkan'}</small></p>${attended?'':'<button data-go="21">Beli tiket</button>'}</div><div><span>${attended?'✓':'3'}</span><p><b>Teman berangkat</b><small>${attended?'6 teman ditemui':'Belum ada Circle'}</small></p><button data-go="25">${attended?'Lihat Circle':'Cari teman'}</button></div></div><div class="hub-grid"><button data-go="19"><b>◎ Grup event</b><span>2 grup aktif · 12 pesan baru</span></button><button data-go="25"><b>◉ Circle cocok</b><span>8 orang satu frekuensi</span></button><button data-go="20"><b>☷ Rundown & venue</b><span>Jadwal, lokasi, dan informasi tiket</span></button>${attended?'<button data-open-own-history><b>▧ Album resmi</b><span>Dokumentasi dari promotor</span></button>':'<button data-go="26"><b>⌖ Check-in</b><span>Aktif saat berada di venue</span></button>'}</div>`}<div class="hub-announcement"><b>Pengumuman promotor</b><p>Gate dibuka pukul 09.00. Siapkan tiket dan identitas sebelum masuk.</p><small>2 jam lalu</small></div></div>`}
